# partition.py
# Determines that no valid partition exists for the given list L and reports it.
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

# Simple exhaustive back‑track search (pruned) to verify impossibility.
from itertools import combinations

def find_partition(nums):
    nums = list(nums)
    n = len(nums)
    triples = []
    # Pre‑compute all valid triples
    valid = []
    for a, b, c in combinations(nums, 3):
        if a + b == c or a + c == b or b + c == a:
            # store sorted (small,mid,large) where small+mid=large
            s, m, l = sorted((a, b, c))
            if s + m == l:
                valid.append((s, m, l))
    # backtrack
    used = set()
    def backtrack(start, selected):
        if len(selected) == 15:
            return selected
        for triple in valid:
            if any(x in used for x in triple):
                continue
            for x in triple:
                used.add(x)
            res = backtrack(start+1, selected+[triple])
            if res:
                return res
            for x in triple:
                used.remove(x)
        return None
    return backtrack(0, [])

result = find_partition(L)
if result is None:
    witness = {"polarity": "negative", "basis": "proof", "argument": "Exhaustive search found no valid partition for the given list."}
else:
    witness = {"polarity": "positive", "data": {"triples": result}}
print("WITNESS: " + __import__('json').dumps(witness))

import itertools, sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# Precompute all valid triples (a,b,c) with a<b and a+b=c
triples = []
for a,b,c in itertools.permutations(L,3):
    if a<b and a+b==c:
        triples.append((a,b,c))
# Sort for deterministic search
triples.sort()
# Build adjacency: for each number, which triples contain it
adj = {x: [] for x in L}
for t in triples:
    for x in t:
        adj[x].append(t)
# Backtracking search
used = set()
solution = []

def search():
    if len(used)==len(L):
        return True
    # choose the unused number with fewest candidate triples (MRV)
    candidates = [(len([t for t in adj[x] if all(y not in used for y in t)]), x) for x in L if x not in used]
    _, chosen = min(candidates)
    for t in adj[chosen]:
        if any(y in used for y in t):
            continue
        # take this triple
        solution.append(t)
        used.update(t)
        if search():
            return True
        # backtrack
        used.difference_update(t)
        solution.pop()
    return False

found = search()
if found:
    witness = {"polarity":"positive","evidence":{"path":"execution://witness"},"data":solution}
    print("WITNESS: "+json.dumps(witness))
else:
    witness = {"polarity":"negative","evidence":{"path":"execution://witness"},"basis":"proof","argument":"No set of 15 disjoint triples satisfying a+b=c exists for the given list."}
    print("WITNESS: "+json.dumps(witness))

